s = sys.stdin.read().split()[0]
n = len(s)
best = 0
for mask in range(1 << n):
    t = [s[i] for i in range(n) if (mask >> i) & 1]
    i = 0
    while i < len(t) and t[i] == 'a':
        i += 1
    while i < len(t) and t[i] == 'b':
        i += 1
    while i < len(t) and t[i] == 'a':
        i += 1
    if i == len(t):
        best = max(best, len(t))
print(best)

